def remove_covered_intervals(intervals):
    sorted_intervals = sorted(intervals, key=lambda p: (p[0], -p[1]))

    count = 0
    max_end = 0
    for _, end in sorted_intervals:
        if end > max_end:
            count += 1
            max_end = end

    return count

